"""Render ``docs/ontology-coverage.md`` ("what the crosswalk covers") from a store.

Every number comes from :func:`functions.coverage_table`, which reads only the
committed files. ``tests/test_foundry_ontology.py`` regenerates the page and
fails if the committed copy differs.
"""
from __future__ import annotations

from .functions import coverage_table
from .runtime import ObjectStore


def render_coverage_md(store: ObjectStore) -> str:
    t = coverage_table(store)
    out = [
        "# What the crosswalk covers",
        "",
        "Generated by `python3 -m ehs_hfo.foundry --coverage-md docs/ontology-coverage.md` from "
        "`ontology/ehs-hfo.ttl`, `crosswalk/`, and `incidents/`. Do not edit by hand; a test "
        "regenerates it.",
        "",
        f"The ontology holds {len(store.objects('Pif'))} PIFs in {len(store.objects('ContextDimension'))} "
        f"context dimensions, {t['rules']} suggester rules, {len(store.objects('CrosswalkEntry'))} "
        f"crosswalk entries and {len(store.objects('AssertedAbsence'))} asserted absences. The incident "
        f"layer is the CSB set only: {t['investigations']} investigations, {t['investigations_coded']} "
        f"of them coded, {t['excerpts']} quoted excerpts. There is no other incident data in the "
        "repository.",
        "",
        "## By framework",
        "",
        "Items reached = framework items at least one PIF maps to through a crosswalk entry. "
        "Dimension-level items are bound to a context dimension, not to a factor, so they have no "
        "entries (IDHEAS-G). PIFs unaddressed = PIFs with neither an entry nor an asserted absence "
        "for that framework. Rules = active rules written against an item of that framework.",
        "",
        "| Framework | Items | Items reached | Dimension-level items | Entries | Close | Partial | Broader "
        "| PIFs with counterpart | PIFs asserted absent | PIFs unaddressed | Rules |",
        "|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|",
    ]
    for f in t["frameworks"]:
        out.append(f"| {f['framework']} | {f['items']} | {f['items_reached']} | {f['dimension_level_items']} "
                   f"| {f['entries']} | {f['close']} | {f['partial']} | {f['broader']} "
                   f"| {f['pifs_with_counterpart']} | {f['pifs_asserted_absent']} "
                   f"| {f['pifs_unaddressed']} | {f['rules']} |")
    out += ["", "## By PIF", "",
            "Frameworks = frameworks with at least one entry for the PIF. Excerpts and investigations "
            "are CSB evidence coded to the PIF (rejected excerpts excluded).", "",
            "| Dimension | PIF | Frameworks | Entries | Rules | Excerpts | Investigations |",
            "|---|---|---:|---:|---:|---:|---:|"]
    for p in t["pifs"]:
        out.append(f"| {p['dimension']} | {p['pif']} | {p['frameworks_with_counterpart']} | {p['entries']} "
                   f"| {p['rules']} | {p['excerpts']} | {p['investigations']} |")
    return "\n".join(out) + "\n"
